#nav{display:flex;flex-direction:column;gap:6px}
.nv{display:flex;align-items:center;gap:10px;width:100%;text-align:left;cursor:pointer;
  background:var(--panel);border:1px solid var(--line);border-radius:10px;padding:10px 12px;color:var(--text)}
.nv:hover{border-color:var(--accent)}
.nv.sel{border-color:var(--accent);box-shadow:0 0 0 1px var(--accent) inset}
.nv.lock{opacity:.55}
.nv-l{width:24px;height:24px;border-radius:7px;display:grid;place-items:center;font-weight:700;font-size:12px;flex:none;
  background:var(--panel2);border:1px solid var(--line);color:var(--muted)}
.nv-l.done{background:rgba(51,196,124,.15);border-color:rgba(51,196,124,.5);color:var(--ok)}
.nv-l.cur{background:rgba(91,140,255,.18);border-color:var(--accent);color:var(--accent)}
.nv-t{flex:1;font-size:13px;font-weight:600}
.nv-w{font-style:normal;font-size:10px;color:var(--warn);border:1px solid rgba(242,169,59,.5);border-radius:999px;padding:0 6px;margin-left:6px}
.nv-c{font-family:var(--mono);font-size:11px;color:var(--muted)}
.legend{margin-top:18px;border:1px dashed var(--line);border-radius:10px;padding:12px;font-size:12px;color:var(--muted);display:grid;gap:7px}
.legend-note{border-top:1px dashed var(--line);padding-top:8px;color:#6d7a92}

/* 中：主面板 */
.col-main{min-width:0}
.flowstrip{display:flex;align-items:stretch;gap:6px;margin-bottom:12px;flex-wrap:wrap}
.fs{flex:1;min-width:110px;display:grid;gap:2px;text-align:left;cursor:pointer;padding:8px 12px;border-radius:10px;
  background:var(--panel);border:1px solid var(--line);color:var(--text)}
.fs:hover{border-color:var(--accent)}
.fs.sel{border-color:var(--accent);box-shadow:0 0 0 1px var(--accent) inset}
.fs.lock{opacity:.55}
.fs-l{font-size:10px;letter-spacing:1.5px;color:var(--muted)}
.fs.done .fs-l{color:var(--ok)}
.fs.cur .fs-l{color:var(--accent)}
.fs-t{font-size:13px;font-weight:700}
.fs-c{font-family:var(--mono);font-size:11px;color:var(--muted)}
.fs-w{position:static;font-size:10px;color:var(--warn)}
.fs-arrow{align-self:center;color:var(--line);font-size:14px}

.banner{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap;
  border-radius:10px;padding:12px 14px;margin-bottom:12px;font-size:13px}
.banner.open{border:1px solid rgba(57,194,215,.5);background:linear-gradient(90deg,rgba(57,194,215,.14),rgba(57,194,215,.03));color:var(--recover)}
.banner.sealed{border:1px solid rgba(51,196,124,.4);background:rgba(51,196,124,.08);color:var(--ok)}
.banner .mono{font-size:12px}

.stage{background:var(--panel);border:1px solid var(--line);border-radius:14px;padding:16px 18px 18px}
.stage.locked{opacity:.75}
.stage-h{display:flex;align-items:flex-start;gap:12px;border-bottom:1px solid var(--line-soft);padding-bottom:12px;margin-bottom:6px}
.stage-letter{width:34px;height:34px;border-radius:9px;display:grid;place-items:center;font-weight:800;flex:none;
  background:var(--panel2);border:1px solid var(--line);color:var(--muted)}
.stage-letter.done{background:rgba(51,196,124,.15);border-color:rgba(51,196,124,.5);color:var(--ok)}
.stage-letter.active{background:rgba(91,140,255,.18);border-color:var(--accent);color:var(--accent)}
.stage-meta{flex:1}
.stage-meta h2{font-size:16px}
.stage-meta p{font-size:12px;color:var(--muted)}
.stage-side{text-align:right;display:grid;gap:2px}
.stage-count{font-family:var(--mono);font-size:13px;color:var(--text)}
.stage-state{font-size:11px;color:var(--muted)}
.stage-state.done{color:var(--ok)}
.stage-state.active{color:var(--accent)}

/* 步骤卡 */
.step{background:var(--panel2);border:1px solid var(--line-soft);border-left:3px solid var(--line);
  border-radius:10px;padding:13px 15px;margin-top:10px}
.step.active{border-left-color:var(--accent)}
.step.done{border-left-color:var(--ok)}
.step.locked{opacity:.55}
.step.irrev{border-color:rgba(242,169,59,.28)}
.step-h{display:flex;align-items:center;gap:10px}
.step-h h3{font-size:14px;flex:1;min-width:0}
.sdot{width:24px;height:24px;border-radius:50%;display:grid;place-items:center;font-size:11px;font-weight:700;flex:none;
  background:var(--panel);border:1px solid var(--line);color:var(--muted);font-family:var(--mono)}
.sdot.done{background:rgba(51,196,124,.15);border-color:rgba(51,196,124,.55);color:var(--ok)}
.sdot.active{background:rgba(91,140,255,.16);border-color:var(--accent);color:var(--accent)}
.step-state{font-size:11px;color:var(--muted);white-space:nowrap}
.step-state.done{color:var(--ok)}
.step-state.active{color:var(--accent)}
.desc{font-size:12.5px;color:var(--muted);margin:6px 0 4px;max-width:70ch}
.lockednote{font-size:12px;color:#5d6a83;margin-top:6px}

.badge{display:inline-block;font-size:10.5px;padding:1px 8px;border-radius:999px;border:1px solid;vertical-align:1px}
.badge.irrev{color:var(--warn);border-color:rgba(242,169,59,.55);background:rgba(242,169,59,.1)}
.badge.recov{color:var(--recover);border-color:rgba(57,194,215,.55);background:rgba(57,194,215,.1)}

.ev{margin:8px 0 2px;display:grid;gap:4px;font-size:12px;color:var(--muted);list-style:none}
.ev li::before{content:"·";color:var(--accent);font-weight:800;margin-right:7px}

.btnrow{display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin-top:10px}
.btn{cursor:pointer;border:1px solid transparent;border-radius:8px;padding:8px 14px;font-size:13px;font-weight:600;
  background:var(--accent);color:#fff;font-family:inherit}
.btn:hover{filter:brightness(1.12)}
.btn.ghost{background:transparent;border-color:var(--line);color:var(--muted)}
.btn.ghost:hover{border-color:var(--accent);color:var(--text)}
.btn.danger{background:var(--danger)}
.btn.ok{background:var(--ok)}
.btn.recov{background:transparent;border-color:var(--recover);color:var(--recover)}
.btn.recov:hover{background:rgba(57,194,215,.12);filter:none}
.btn.big{padding:12px 22px;font-size:15px}
.btn.sm{padding:4px 10px;font-size:12px}
.btn:disabled{opacity:.45;cursor:not-allowed;filter:none}
.hint{font-size:11.5px;color:#5d6a83;margin-top:7px}
.hint.bad{color:var(--warn)}
.warnnote{color:var(--warn)}
.doneline{color:var(--ok);font-size:13px;margin-top:8px;font-weight:600}
.doneline.inline{margin-top:0}
.armedline{color:var(--ok);font-size:13px;margin-top:9px;font-weight:700}
.recovnote{font-size:12px;color:var(--recover);margin-top:8px}

.checks{display:grid;gap:8px;margin-top:10px}
.check{display:flex;gap:9px;align-items:flex-start;font-size:13px;cursor:pointer;
  border:1px solid var(--line-soft);border-radius:8px;padding:8px 10px;background:var(--panel)}
.check:hover{border-color:var(--accent)}
.check input{margin-top:3px;accent-color:var(--ok)}
.check input:disabled{cursor:not-allowed}

.metrics{margin-top:10px;border:1px solid var(--line-soft);border-radius:8px;overflow:hidden;max-width:440px}
.mrow{display:grid;grid-template-columns:56px 1fr 1fr;font-family:var(--mono);font-size:12px;
  padding:5px 12px;border-top:1px solid var(--line-soft);color:var(--text)}
.mrow:first-child{border-top:0;background:var(--panel);color:var(--muted);font-family:inherit;font-size:11px}
.mrow.warn{background:rgba(242,169,59,.1)}
.mrow.warn span{color:var(--warn)}

.rlines{margin-top:10px;display:grid;gap:3px;font-family:var(--mono);font-size:12px;color:var(--recover)}
.rlines .head{color:var(--accent);font-weight:700}

.finishbar{display:flex;align-items:center;gap:14px;flex-wrap:wrap;margin-top:16px;
  border:1px solid rgba(51,196,124,.4);background:rgba(51,196,124,.07);border-radius:10px;padding:14px}
.finishbar span{font-size:12px;color:var(--muted)}
.gocur{margin-top:12px;text-align:center}

/* 指挥日志 */
.col-log #log{list-style:none;display:grid;gap:2px;max-height:calc(100vh - 120px);overflow:auto;
  border:1px solid var(--line);border-radius:10px;background:var(--panel2);padding:10px}
#log li{display:flex;gap:8px;font-family:var(--mono);font-size:11.5px;color:var(--muted);padding:3px 2px;border-radius:5px}
#log li .lt{color:#54627e;flex:none}
#log li.ok{color:var(--ok)}
#log li.warn{color:var(--warn)}
#log li.danger{color:var(--danger)}
#log li.recover{color:var(--recover)}

/* ---------- 模态 ---------- */
.overlay{display:none;position:fixed;inset:0;z-index:50;background:rgba(4,7,14,.72);backdrop-filter:blur(4px);
  align-items:center;justify-content:center;padding:20px}
.overlay.show{display:flex}
.modal{width:min(660px,94vw);max-height:92vh;overflow:auto;background:#141d31;border:1px solid #2b3a58;
  border-radius:14px;padding:20px 22px;animation:pop .18s ease-out}
.modal.danger{border-top:3px solid var(--danger)}
.modal.recover{border-top:3px solid var(--recover)}
.modal.certify.good{border-top:3px solid var(--ok)}
@keyframes pop{from{transform:translateY(10px);opacity:0}to{transform:none;opacity:1}}
.modal header{display:flex;gap:12px;align-items:center}
.modal header h3{font-size:17px}
.m-icon{width:40px;height:40px;border-radius:10px;display:grid;place-items:center;font-size:19px;flex:none;
  background:rgba(239,83,80,.12);border:1px solid rgba(239,83,80,.5);color:var(--danger)}
.modal.recover .m-icon{background:rgba(57,194,215,.12);border-color:rgba(57,194,215,.5);color:var(--recover)}
.m-sub{font-size:12px;color:var(--muted);margin-top:2px}
.m-intro{font-size:13px;color:var(--text);margin:12px 0;border-left:3px solid var(--line);padding-left:12px}
.m-boxes{display:grid;gap:8px;margin:12px 0}
.m-box{display:flex;gap:10px;align-items:flex-start;font-size:13px;border:1px solid var(--line);
  border-radius:8px;padding:9px 11px;cursor:pointer;background:var(--panel2)}
.m-box:hover{border-color:var(--accent)}
.m-box input{margin-top:3px;accent-color:var(--danger)}
.m-phrase label{font-size:12px;color:var(--muted)}
.m-phrase input{width:100%;margin-top:6px;background:#0a0f1b;border:1px solid var(--line);border-radius:8px;
  color:var(--text);font-family:var(--mono);font-size:14px;padding:10px 12px;outline:none}
.m-phrase input:focus{border-color:var(--accent)}
.m-hint{font-size:11.5px;color:#5d6a83;margin-top:5px}
.modal footer{display:flex;justify-content:flex-end;gap:10px;margin-top:16px}

/* 完成证书 */
.certify{text-align:center}
.cert-badge{width:72px;height:72px;margin:6px auto 10px;border-radius:50%;display:grid;place-items:center;font-size:34px;
  background:rgba(51,196,124,.12);border:2px solid var(--ok);color:var(--ok)}
.certify:not(.good) .cert-badge{background:rgba(242,169,59,.12);border-color:var(--warn);color:var(--warn)}
.certify h2{font-size:22px}
.cert-sub{font-size:12.5px;color:var(--muted);margin:6px 0 14px}
.cert-stats{display:flex;justify-content:center;gap:10px;flex-wrap:wrap;margin:12px 0}
.cert-stats div{border:1px solid var(--line);border-radius:10px;padding:10px 18px;display:grid;gap:2px;background:var(--panel2)}
.cert-stats i{font-style:normal;font-family:var(--mono);font-size:19px;color:var(--text)}
.cert-stats span{font-size:11px;color:var(--muted)}
.cert-zero{color:var(--ok);font-weight:700;font-size:13px;margin:8px 0}
.cert-mistakes{list-style:none;text-align:left;display:grid;gap:4px;margin:10px 0;font-size:12px;color:var(--warn)}
.cert-mistakes li{border:1px dashed rgba(242,169,59,.4);border-radius:7px;padding:6px 10px}
.cert-actions{display:flex;justify-content:center;gap:10px;margin-top:14px}

/* Toast */
#toasts{position:fixed;left:50%;bottom:22px;transform:translateX(-50%);z-index:80;display:grid;gap:8px;justify-items:center}
.toast{background:#161f33;border:1px solid var(--accent);color:var(--text);border-radius:999px;
  padding:9px 18px;font-size:13px;box-shadow:0 8px 24px rgba(0,0,0,.5);animation:pop .18s ease-out;white-space:nowrap}
.toast.ok{border-color:var(--ok);color:var(--ok)}
.toast.danger{border-color:var(--warn);color:var(--warn)}
.toast.out{opacity:0;transition:opacity .3s}

@keyframes shake{0%,100%{transform:none}20%,60%{transform:translateX(-5px)}40%,80%{transform:translateX(5px)}}
.shake{animation:shake .45s}

@media (max-width:1180px){
  .layout{grid-template-columns:1fr}
  .col-nav #nav{flex-direction:row;flex-wrap:wrap}
  .nv{width:auto;flex:1;min-width:150px}
  .col-log #log{max-height:320px}
}

input.content:
'use strict';

/* ============================================================
   RELEASEROOM · 发版指挥台
   cell-j10-s09 · complete × consequential-flow
   用户任务：零失误走完一个高后果发布流程；
   不可逆步骤（全量发布 / 密封回滚窗口）执行前强制确认、
   执行后提供回滚恢复路径，直至窗口被密封。
   所有数据随首屏内联 — 无任何异步加载。
   ============================================================ */

const FLOW = {
  meta: {
    product: 'checkout-api',
    version: 'v2.14.0',
    prev: 'v2.13.7',
    env: 'PRODUCTION',
    windowText: '今日 14:00–15:00 · UTC+8',
    instances: 48,
  },
  stages: [
    { id:'A', title:'预检',      goal:'发布前事实核对 — 全部通过才可进入灰度', steps:['a1','a2','a3'] },
    { id:'B', title:'灰度验证',  goal:'5% 灰度采集 7 个采样周期，指标达标后闭合', steps:['b1','b2'] },
    { id:'C', title:'全量发布',  goal:'执行不可逆切换 — 强制确认前置 + 回滚窗口兜底', steps:['c1','c2'], irreversible:true },
    { id:'D', title:'验证与收尾', goal:'冒烟通过 → 密封回滚窗口 → 归档', steps:['d1','d2','d3'] },
  ],
  steps: {
    a1:{stage:'A',kind:'check',title:'确认 CI 主干绿灯',desc:'主发布流水线全部通过，质量门禁无豁免。',
      ev:['流水线 release/2.14.0 · #4821 — 通过','测试 217/217 · 覆盖率 84.3%（门禁 ≥ 82%）','镜像 sha256:9f21c…e04b 已归档']},
    a2:{stage:'A',kind:'check',title:'发布公告已发出',desc:'#announce 已通知窗口、影响范围与回滚预案。',
      ev:['接收方：业务方 · 客服 · 支付网关','预期影响：发布期间下单延迟 +200ms 以内']},
    a3:{stage:'A',kind:'check',title:'与值班 SRE 完成对齐',desc:'值班知悉窗口；回滚预案已于昨日演练通过。',
      ev:['值班 SRE：已应答（09:12）','回滚演练 2026-09-08：通过 · 耗时 9m12s']},
    b1:{stage:'B',kind:'action',title:'部署 5% 灰度',desc:'12 台实例切入 v2.14.0，其余 36 台保持 v2.13.7。此步可逆 — 确认灰度前可撤销重做。',
      runLabel:'部署 5% 灰度',undoLabel:'撤销灰度（可逆）',
      lines:['解析镜像 sha256:9f21c…e04b','实例替换 4/12','实例替换 8/12','实例替换 12/12 · 健康检查通过'],
      doneText:'canary 5% 已部署 · 12/12 实例就绪'},
    b2:{stage:'B',kind:'observe',title:'观察灰度指标 · 7 个采样周期',desc:'逐周期采集错误率与 p99。7/7 达标后由你确认闭合 — 证据不足时确认将记一次失误。',
      confirmLabel:'确认灰度达标 · 闭合阶段'},
    c1:{stage:'C',kind:'gate',title:'全量发布前置核对',desc:'三项全部勾选后，发布进入待命。此步可逆 — 未执行前可反复核对修改。',
      checks:[
        {id:'c1a',text:'灰度 7/7 采样达标，当前无未处理 P2 以上告警'},
        {id:'c1b',text:'客服与支付侧已再次知情（近 10 分钟内）'},
        {id:'c1c',text:'回滚预案就绪：v2.13.7 镜像已在全部实例预热'}],
      armedText:'前置核对完成 · 发布待命'},
    c2:{stage:'C',kind:'irrev',title:'执行全量发布',desc:'48 台实例全部切换至 v2.14.0。不可逆 — 执行前强制确认；执行后回滚窗口保持开启，直至 D 阶段密封。',
      doneText:'已执行 · 48/48 实例上线 v2.14.0',
      lockedHint:'前置核对未完成 — 未待命时尝试执行将记一次失误'},
    d1:{stage:'D',kind:'action',title:'生产冒烟测试',desc:'核心链路 3 项探针。运行通过后需你确认。',
      runLabel:'运行冒烟测试',confirmLabel:'确认冒烟通过',
      lines:['GET / → 200 · 183ms','POST /order → 200 · 241ms','POST /pay/notify → 200 · 167ms'],
      doneText:'冒烟 3/3 通过 · 已确认'},
    d2:{stage:'D',kind:'irrev',title:'密封回滚窗口',desc:'密封后回滚入口永久关闭 — 同样不可逆。密封之前，回滚始终可用。',
      doneText:'回滚窗口已密封 · 恢复入口永久关闭',
      lockedHint:'需先完成 D1 冒烟确认 — 未满足时尝试将记一次失误'},
    d3:{stage:'D',kind:'check',title:'发布公告与复盘归档',desc:'对外公告切换为「已上线」，复盘纪要归档至 runbook。',
      ev:['公告状态：已上线（发布前草稿已归档）','复盘纪要：RUNBOOK/release-2.14.0']},
  },
};

const ORDER = ['a1','a2','a3','b1','b2','c1','c2','d1','d2','d3'];
const ERR   = [0.08, 0.12, 0.11, 0.48, 0.15, 0.09, 0.07];   // 错误率 %
const P99   = [212, 198, 221, 486, 203, 189, 194];           // p99 ms
const ERR_T = 0.5, P99_T = 500;

const $ = s => document.querySelector(s);

/* ---------- 状态 ---------- */
let STATE_SEQ = 0;
let S;
function freshState(){
  return {
    seq: ++STATE_SEQ,
    done: new Set(),
    c1: { c1a:false, c1b:false, c1c:false },
    canarySamples: [], canaryP99: [],
    smoke: { run:false },
    win: { openAt:null, sealed:false },
    counts: { rollout:0, rollback:0 },
    mistakes: [], log: [],
    view:'A', follow:true,
    startAt: Date.now(),
    finished:false, overlayClosed:false,
    running:false, resetArm:false, resetArmUntil:0,
  };
}

/* ---------- 派生 ---------- */
const stageById    = id => FLOW.stages.find(s => s.id === id);
const stageSteps   = id => stageById(id).steps;
const stepDone     = id => S.done.has(id);
const stageComplete= id => stageSteps(id).every(stepDone);
const stageActive  = id => FLOW.stages.slice(0, FLOW.stages.findIndex(s => s.id === id)).every(st => stageComplete(st.id));
const c1Armed      = () => S.c1.c1a && S.c1.c1b && S.c1.c1c;
function currentStageId(){ return (FLOW.stages.find(s => !stageComplete(s.id)) || FLOW.stages[3]).id; }
const elapsed = () => Math.floor((Date.now() - S.startAt) / 1000);
const mmss    = s => String(Math.floor(s/60)).padStart(2,'0') + ':' + String(s%60).padStart(2,'0');
const stepNo  = id => ORDER.indexOf(id) + 1;

/* ---------- 反馈 ---------- */
function addLog(kind, text){ S.log.push({ t:mmss(elapsed()), kind, text }); renderLog(); }
function toast(text, kind){
  const el = document.createElement('div');
  el.className = 'toast ' + (kind || 'info');
  el.textContent = text;
  $('#toasts').appendChild(el);
  setTimeout(() => { el.classList.add('out'); setTimeout(() => el.remove(), 320); }, 2700);
}
function mistake(text, stepId){
  S.mistakes.push({ t:mmss(elapsed()), text, step:stepId || '' });
  addLog('warn', '失误 +1 — ' + text);
  toast('失误 +1 · ' + text, 'danger');
  renderChips();
}
function shake(id){
  const el = document.getElementById('step-' + id);
  if(!el) return;
  el.classList.remove('shake'); void el.offsetWidth;
  el.classList.add('shake');
  setTimeout(() => el.classList.remove('shake'), 500);
}

/* ---------- 带进度的模拟执行 ---------- */
function runWithLines(stepId, label, lines, done){
  if(S.running){ toast('操作进行中，请稍候'); return; }
  S.running = true;
  const box = document.getElementById('run-' + stepId);
  if(box) box.innerHTML = '<div class="rline head">▸ ' + label + '</div>';
  const seq0 = S.seq;
  let i = 0;
  const iv = setInterval(() => {
    if(S.seq !== seq0){ clearInterval(iv); S.running = false; return; }
    if(i < lines.length){
      if(box) box.insertAdjacentHTML('beforeend', '<div class="rline">▸ ' + lines[i++] + '</div>');
    } else {
      clearInterval(iv); S.running = false; done();
    }
  }, 380);
}

/* ---------- 渲染 ---------- */
function renderChips(){
  const stagesDone = FLOW.stages.filter(stageComplete).length;
  const mtitle = S.mistakes.length ? S.mistakes.map(m => m.t + ' ' + m.text).join('；') : '当前零失误';
  $('#chips').innerHTML =
    '<span class="chip mono">' + FLOW.meta.product + ' · ' + FLOW.meta.version + '</span>' +
    '<span class="chip">' + FLOW.meta.env + ' · ' + FLOW.meta.windowText + '</span>' +
    '<span class="chip ' + (S.mistakes.length ? 'bad' : 'good') + '" id="mistakeChip" title="' + mtitle + '">失误 ' + S.mistakes.length + '</span>' +
    '<span class="chip">' + S.done.size + '/10 步 · 阶段 ' + stagesDone + '/4</span>' +
    '<span class="chip mono" id="clock">' + mmss(elapsed()) + '</span>' +
    '<button class="btn ghost sm" data-action="reset" id="resetBtn">重置演练</button>';
  $('#pfill').style.width = (S.done.size / ORDER.length * 100) + '%';
}

function renderNav(){
  $('#nav').innerHTML = FLOW.stages.map(s => {
    const done = stageComplete(s.id), act = stageActive(s.id);
    const cls = done ? 'done' : act ? 'cur' : 'lock';
