      phrase:'ROLLBACK',
      actionLabel:'执行回滚',
      lines:['切回镜像 ' + m.prev,'实例替换 18/48','实例替换 48/48 · 路由恢复'],
      onDone(){
        S.done.delete('c2'); S.done.delete('d1');
        S.smoke.run = false;
