        S.counts.rollback++; S.follow = true;
        addLog('recover', '已回滚至 ' + m.prev + ' — 全量发布恢复/撤销，C2 复位为待命');
        toast('已回滚 · 发布复位为待命，可重新执行', 'ok');
        renderAll();
      }
    }),
    seal: () => ({
      sev:'danger',
