482	document.addEventListener('click', e => {
483	  const el = e.target.closest('[data-action]');
484	  if(!el) return;
485	  const a = el.dataset.action;
486	
487	  switch(a){
488	    case 'nav-stage':
489	      S.view = el.dataset.stage;
