491	      renderPanel(); renderNav();
492	      break;
493	
494	    case 'go-current':
495	      S.follow = true;
496	      renderPanel(); renderNav();
497	      break;
498	
499	    case 'toggle-check': {
500	      const id = el.dataset.step;
501	      if(stepDone(id) || checkToggleAllowed(id)){
502	        if(stepDone(id)) S.done.delete(id);
503	        else { S.done.add(id); addLog('ok', stepNo(id) + ' 已核对 — ' + FLOW.steps[id].title); }
504	        renderAll();
505	      } else toast('该核对项已随阶段闭合锁定');
506	      break;
507	    }
508	
509	    case 'toggle-c1': {
510	      if(stepDone('c2') || el.disabled) break;
511	      const was = c1Armed();
512	      S.c1[el.dataset.check] = !S.c1[el.dataset.check];
513	      const now = c1Armed();
514	      if(!was && now) addLog('ok', 'C1 前置核对完成 — 发布待命');
515	      if(was && !now) addLog('info', 'C1 前置核对被撤回 — 发布退出待命');
516	      renderPanel();
517	      break;
518	    }
519	
520	    case 'sample': {
521	      const n = S.canarySamples.length;
522	      if(n >= 7 || stepDone('b2')) break;
523	      S.canarySamples.push(ERR[n]); S.canaryP99.push(P99[n]);
524	      const warn = ERR[n] >= ERR_T || P99[n] >= P99_T;
525	      addLog(warn ? 'warn' : 'info', 'B2 采样 ' + (n+1) + '/7 — 错误率 ' + ERR[n].toFixed(2) + '% · p99 ' + P99[n] + 'ms' + (warn ? '（预警，未破线）' : ''));
526	      renderPanel();
527	      break;
528	    }
529	
530	    case 'confirm-b2':
531	      if(S.canarySamples.length < 7){
532	        mistake('灰度证据不足（采样 ' + S.canarySamples.length + '/7）即确认达标', 'b2'); shake('b2'); break;
533	      }
534	      S.done.add('b2');
535	      addLog('ok', 'B2 灰度达标已确认 — 7/7 采样 · 错误率峰值 0.48% 未破线');
536	      toast('灰度阶段闭合', 'ok');
537	      renderAll();
538	      break;
539	
540	    case 'run-b1':
541	      runWithLines('b1', FLOW.steps.b1.runLabel, FLOW.steps.b1.lines, () => {
542	        S.done.add('b1'); addLog('ok', 'B1 canary 5% 已部署 · 12/12 实例就绪'); renderAll();
543	      });
544	      break;
545	
546	    case 'undo-b1':
547	      S.done.delete('b1'); S.canarySamples = []; S.canaryP99 = [];
548	      addLog('info', 'B1 灰度已撤销（可逆步骤）— 采样清零');
549	      renderAll();
550	      break;
551	
552	    case 'run-d1':
553	      runWithLines('d1', FLOW.steps.d1.runLabel, FLOW.steps.d1.lines, () => {
554	        S.smoke.run = true; addLog('info', 'D1 冒烟测试 3/3 通过 — 待确认'); renderAll();
555	      });
556	      break;
557	
558	    case 'confirm-d1':
559	      S.done.add('d1'); addLog('ok', 'D1 冒烟通过已确认'); renderAll();
560	      break;
561	
562	    case 'open-c2':
563	      if(stepDone('c2')) break;
564	      if(!(stageActive('C') && c1Armed())){ mistake('前置核对未完成即尝试执行全量发布', 'c2'); shake('c2'); break; }
565	      openModal('rollout');
566	      break;
567	
568	    case 'rollback':
569	      if(S.win.openAt && !S.win.sealed) openModal('rollback');
570	      break;
571	
572	    case 'seal':
573	      if(S.win.sealed || stepDone('d2')) break;
574	      if(!(stepDone('d1') && S.win.openAt)){ mistake('冒烟未确认即尝试密封回滚窗口', 'd2'); shake('d2'); break; }
575	      openModal('seal');
576	      break;
577	
578	    case 'finish':
579	      if(ORDER.every(stepDone)){
580	        S.finished = true;
581	        addLog('ok', '发布流程闭合 — 交接记录已生成');
582	        renderAll();
583	      } else { mistake('流程未闭合即尝试完成', 'd3'); shake('d3'); }
584	      break;
585	
586	    case 'reset': {
587	      const now = Date.now();
588	      if(!S.resetArm || now > S.resetArmUntil){
589	        S.resetArm = true; S.resetArmUntil = now + 3000;
590	        el.textContent = '确认重置？';
591	        setTimeout(() => { S.resetArm = false; const b = document.getElementById('resetBtn'); if(b) b.textContent = '重置演练'; }, 3000);
592	        break;
593	      }
594	      S = freshState(); bootLog(); renderAll(); toast('已重置', 'ok');
595	      break;
