597	
598	    case 'reset2':
599	      S = freshState(); bootLog(); renderAll(); toast('已重置', 'ok');
600	      break;
601	
602	    case 'modal-cancel': if(M && !M.exec) closeModal(); break;
603	    case 'modal-confirm': modalConfirm(); break;
604	
605	    case 'close-completion':
606	      S.overlayClosed = true; renderCompletion(); break;
607	  }
608	});
